<?php
namespace Tests\Feature\Finance;
class ModernFinanceServiceCatalogTest extends ModernFinanceCatalogTestCase { public function test_list_create_edit_and_no_delete_route():void{$this->actingAs($this->user)->get(route('dashboard.finance.services.index'))->assertOk()->assertSee('Услуги и сборы');$r=$this->actingAs($this->user)->post(route('dashboard.finance.services.store'),['name_ru'=>'Питание','category'=>'food','type'=>'service','payment_period'=>'monthly','is_active'=>1]);$fee=\App\Models\Fee::where('name_ru','Питание')->firstOrFail();$r->assertRedirect(route('dashboard.finance.services.show',$fee));$this->actingAs($this->user)->put(route('dashboard.finance.services.update',$fee),['name_ru'=>'Школьное питание','category'=>'food','type'=>'service','payment_period'=>'monthly','is_active'=>1])->assertSessionHasNoErrors();$this->assertDatabaseHas('fees',['id'=>$fee->id,'name_ru'=>'Школьное питание']);$this->assertFalse(\Illuminate\Support\Facades\Route::has('dashboard.finance.services.destroy'));} public function test_russian_validation():void{$this->actingAs($this->user)->post(route('dashboard.finance.services.store'),[])->assertSessionHasErrors('name_ru');$this->assertSame('Укажите название услуги на русском языке.',session('errors')->first('name_ru'));}}
